                    crate::ics::NormalizedTiming::Timed { starts_at, ends_at, timezone } => EventTiming::Timed {
                        start_utc: starts_at.timestamp(), end_utc: ends_at.timestamp(),
                        timezone: timezone.clone().unwrap_or_else(|| "UTC".to_owned()),
                    },
                    crate::ics::NormalizedTiming::AllDay { start_date, end_date } => EventTiming::AllDay {
                        start_date: start_date.format("%Y-%m-%d").to_string(), end_date: end_date.format("%Y-%m-%d").to_string(),
                    },
                };
                let exception_event = EventMutation {
                    title: exception.summary.clone(), description: exception.description.clone(), location: exception.location.clone(),
                    status: match exception.status.as_deref() { Some("TENTATIVE") => EventStatus::Tentative, Some("CANCELLED") => EventStatus::Cancelled, _ => EventStatus::Confirmed },
                    timing: exception_timing,
